class AdvancedWebScraper:
    def __init__(self):
        self.session: Optional[aiohttp.ClientSession] = None
        self.visited_urls: Set[str] = set()
        self.executor = ThreadPoolExecutor(max_workers=3)

    async def create_session(self):
        """Async session létrehozása megfelelő beállításokkal"""
        if self.session is None or self.session.closed:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'hu-HU,hu;q=0.9,en;q=0.8',
                'Accept-Encoding': 'gzip, deflate, br',
                'Connection': 'keep-alive'
            }

            timeout = aiohttp.ClientTimeout(total=30, connect=10, sock_read=20)
            connector = aiohttp.TCPConnector(
                limit=10,
                ttl_dns_cache=300,
                ssl=False
            )

            self.session = aiohttp.ClientSession(
                headers=headers,
                timeout=timeout,
                connector=connector
            )

    async def close_session(self):
        """Session biztonságos lezárása"""
        if self.session and not self.session.closed:
            await self.session.close()
            await asyncio.sleep(0.25)  # Várunk a kapcsolatok lezárására

    def check_robots_txt(self, url: str) -> bool:
        """Egyszerűsített robots.txt ellenőrzés"""
        # Egyszerűsített verzió - alapértelmezetten engedélyez
        return True

    def is_allowed_url(self, url: str, allowed_patterns: List[str]) -> bool:
        """URL pattern ellenőrzés biztonságosan"""
        try:
            for pattern in allowed_patterns:
                if re.match(pattern, url):
                    return True
        except Exception as e:
            logger.error(f"Pattern matching hiba: {e}")
        return False

    async def discover_urls_with_exa(self, domain: str, query: str) -> Set[str]:
        """Exa AI URL felfedezés async módon"""
        discovered = set()
        try:
            if exa_client:
                # Szinkron hívást async módon futtatjuk
                loop = asyncio.get_event_loop()
                search_results = await loop.run_in_executor(
                    self.executor,
                    lambda: exa_client.search(
                        query=f"site:{domain} {query}",
                        num_results=20,
                        use_autoprompt=True
                    )
                )

                for result in search_results.results:
                    if result.url:
                        discovered.add(result.url)

        except Exception as e:
            logger.error(f"Exa keresési hiba {domain}-re: {e}")

        return discovered

    async def analyze_page_with_grok(self, html: str, url: str) -> Dict:
        """Grok AI oldal elemzés async módon"""
        try:
            if not xai_client:
                return {}

            # HTML rövidítése
            html_snippet = html[:3000] if len(html) > 3000 else html

            prompt = f"""Elemezd ezt a weboldalt és találj akciós termékeket.
URL: {url}

Térj vissza JSON formátumban:
{{"products": [], "categories": [], "product_links": []}}

HTML: {html_snippet}"""

            loop = asyncio.get_event_loop()
            response = await loop.run_in_executor(
                self.executor,
                lambda: xai_client.chat.completions.create(
                    model="grok-beta",
                    messages=[
                        {"role": "system", "content": "JSON elemző AI vagy."},
                        {"role": "user", "content": prompt}
                    ],
                    max_tokens=1000,
                    temperature=0.1
                )
            )

            result = response.choices[0].message.content
            try:
                return json.loads(result)
            except:
                return {"products": [], "categories": [], "product_links": []}

        except Exception as e:
            logger.error(f"Grok elemzési hiba: {e}")
            return {}

    async def fetch_page(self, url: str) -> str:
        """Weboldal biztonságos letöltése"""
        try:
            await self.create_session()

            async with self.session.get(url, ssl=False, allow_redirects=True) as response:
                if response.status == 200:
                    content = await response.text(errors='ignore')
                    return content
                else:
                    logger.warning(f"HTTP {response.status} - {url}")
                    return ""

        except asyncio.TimeoutError:
            logger.error(f"Timeout - {url}")
        except aiohttp.ClientError as e:
            logger.error(f"Client hiba {url}: {e}")
        except Exception as e:
            logger.error(f"Általános hiba {url}: {e}")

        return ""

    def safe_select_one(self, element, selector: str, default=None):
        """Biztonságos elem kiválasztás"""
        try:
            result = element.select_one(selector)
            return result if result else default
        except Exception:
            return default

    def safe_select(self, element, selector: str):
        """Biztonságos elemek kiválasztása"""
        try:
            return element.select(selector)
        except Exception:
            return []

    def safe_get_text(self, element, default: str = "") -> str:
        """Biztonságos szöveg kinyerés"""
        try:
            if element:
                return element.get_text(strip=True)
        except Exception:
            pass
        return default

    def extract_links(self, html: str, base_url: str, selectors: Dict) -> Set[str]:
        """Linkek biztonságos kinyerése"""
        links = set()
        try:
            soup = BeautifulSoup(html, 'html.parser')

            # Kategória linkek
            category_links = self.safe_select(soup, selectors.get('category_links', 'a'))
            for link in category_links[:20]:  # Maximum 20 link
                href = link.get('href')
                if href:
                    try:
                        full_url = urljoin(base_url, href)
                        if full_url.startswith(('http://', 'https://')):
                            links.add(full_url)
                    except Exception:
                        continue

            # Lapozási linkek
            pagination_links = self.safe_select(soup, selectors.get('pagination', '.pagination a'))
            for link in pagination_links[:10]:
                href = link.get('href')
                if href:
                    try:
                        full_url = urljoin(base_url, href)
                        if full_url.startswith(('http://', 'https://')):
                            links.add(full_url)
                    except Exception:
                        continue

        except Exception as e:
            logger.error(f"Link kinyerési hiba: {e}")

        return links

    def extract_price(self, text: str) -> float:
        """Ár kinyerése szövegből"""
        if not text:
            return 0.0

        try:
            # Eltávolítjuk a nem számjegyeket, meghagyjuk a pontot és vesszőt
            cleaned = re.sub(r'[^\d.,]', '', text)
            # Vessző helyett pont
            cleaned = cleaned.replace(',', '.')
            # Első szám
            match = re.search(r'[\d.]+', cleaned)
            if match:
                return float(match.group())
        except Exception as e:
            logger.debug(f"Ár parse hiba: {e}")

        return 0.0

    def extract_discount_percentage(self, discount_text: str, original_price: float, current_price: float) -> float:
        """Kedvezmény százalék számítás"""
        try:
            # Első: explicit százalék a szövegben
            if discount_text:
                percent_match = re.search(r'(\d+)%', discount_text)
                if percent_match:
                    return float(percent_match.group(1))

            # Második: számítás árakból
            if original_price > 0 and current_price > 0 and original_price > current_price:
                return round(((original_price - current_price) / original_price) * 100, 1)
        except Exception as e:
            logger.debug(f"Kedvezmény számítási hiba: {e}")

        return 0.0

    async def crawl_website_comprehensive(self, site_name: str, config: Dict) -> List[Dict]:
        """Teljes weboldal crawling robosztus hibakezeléssel"""
        products = []
        urls_to_process = set(config['start_urls'])
        processed_urls = set()

        max_pages = 50  # Limit az egyes webhelyekhez
        processed_count = 0

        # Exa URL felfedezés (opcionális)
        try:
            domain = urlparse(config['base_url']).netloc
            exa_urls = await self.discover_urls_with_exa(domain, "akció")
            urls_to_process.update(list(exa_urls)[:20])
        except Exception as e:
            logger.error(f"Exa felfedezési hiba: {e}")

        while urls_to_process and processed_count < max_pages:
            try:
                current_url = urls_to_process.pop()

                if (current_url in processed_urls or 
                    not self.is_allowed_url(current_url, config['allowed_patterns'])):
                    continue

                logger.info(f"[{site_name}] Feldolgozás: {current_url}")
                html = await self.fetch_page(current_url)

                if not html or len(html) < 100:
                    continue

                processed_urls.add(current_url)
                processed_count += 1

                # BeautifulSoup parsing biztonságosan
                try:
                    soup = BeautifulSoup(html, 'html.parser')
                except Exception as e:
                    logger.error(f"HTML parsing hiba: {e}")
                    continue

                # Termékek keresése
                product_elements = self.safe_select(soup, config['selectors']['product'])

                for element in product_elements[:50]:  # Maximum 50 termék/oldal
                    try:
                        title_elem = self.safe_select_one(element, config['selectors']['title'])
                        price_elem = self.safe_select_one(element, config['selectors']['price'])

                        if not title_elem or not price_elem:
                            continue

                        title = self.safe_get_text(title_elem)
                        current_price_text = self.safe_get_text(price_elem)
                        current_price = self.extract_price(current_price_text)

                        if not title or current_price <= 0:
                            continue

                        # Eredeti ár
                        original_price_elem = self.safe_select_one(element, config['selectors']['original_price'])
                        original_price = 0.0
                        if original_price_elem:
                            original_price = self.extract_price(self.safe_get_text(original_price_elem))

                        # Ha nincs eredeti ár, használjuk a jelenlegi árat
                        if original_price <= 0:
                            original_price = current_price

                        # Kedvezmény
                        discount_elem = self.safe_select_one(element, config['selectors']['discount'])
                        discount_text = self.safe_get_text(discount_elem)
                        discount_percent = self.extract_discount_percentage(discount_text, original_price, current_price)

                        # Link
                        link_elem = self.safe_select_one(element, config['selectors']['link'])
                        link = ""
                        if link_elem:
                            href = link_elem.get('href', '')
                            if href:
                                try:
                                    link = urljoin(config['base_url'], href)
                                except Exception:
                                    link = href

                        # Termék hozzáadása
                        product = {
                            'site': site_name,
                            'title': title[:200],  # Maximum 200 karakter
                            'current_price': round(current_price, 2),
                            'original_price': round(original_price, 2),
                            'discount_percent': round(discount_percent, 1),
                            'discount_amount': round(max(0, original_price - current_price), 2),
                            'link': link,
                            'scraped_at': datetime.now().isoformat(),
                            'source_url': current_url,
                            'ai_enhanced': False
                        }

                        # Deduplikáció
                        if not any(p['title'] == product['title'] and p['site'] == product['site'] for p in products):
                            products.append(product)

                    except Exception as e:
                        logger.debug(f"Termék feldolgozási hiba: {e}")
                        continue

                # Új linkek felfedezése
                try:
                    new_links = self.extract_links(html, config['base_url'], config['selectors'])
                    for link in list(new_links)[:10]:  # Maximum 10 új link
                        if link not in processed_urls and len(urls_to_process) < 100:
                            urls_to_process.add(link)
                except Exception as e:
                    logger.error(f"Link felfedezési hiba: {e}")

                # Késleltetés
                await asyncio.sleep(2)

            except Exception as e:
                logger.error(f"Oldal feldolgozási hiba: {e}")
                continue

        logger.info(f"[{site_name}] {len(products)} termék, {processed_count} oldal feldolgozva")
        return products

async def scrape_all_websites_comprehensive():
    """Minden weboldal scraping-je"""
    global scraped_data, last_update, scraping_in_progress

    if scraping_in_progress:
        logger.info("Scraping már folyamatban van")
        return

    scraping_in_progress = True
    logger.info("=== Teljes scraping indítása ===")

    scraper = AdvancedWebScraper()
    all_products = []

    try:
        await scraper.create_session()

        for site_name, config in WEBSITES.items():
            try:
                logger.info(f">>> {site_name} scraping indítása")
                site_products = await scraper.crawl_website_comprehensive(site_name, config)
                all_products.extend(site_products)
                logger.info(f"<<< {site_name}: {len(site_products)} termék")

                # Pihenő webhelyek között
                await asyncio.sleep(5)

            except Exception as e:
                logger.error(f"{site_name} scraping hiba: {e}")
                continue

    except Exception as e:
        logger.error(f"Globális scraping hiba: {e}")

    finally:
        await scraper.close_session()
        scraping_in_progress = False

    # Rendezés kedvezmény szerint
    all_products.sort(key=lambda x: x.get('discount_percent', 0), reverse=True)

    scraped_data = all_products
    last_update = datetime.now()

    logger.info(f"=== Scraping befejezve: {len(all_products)} termék ===")

def run_comprehensive_scraping():
    """Scraping futtatása új event loop-pal"""
    try:
        # Új event loop létrehozása a thread számára
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        loop.run_until_complete(scrape_all_websites_comprehensive())
        loop.close()
    except Exception as e:
        logger.error(f"Scraping futtatási hiba: {e}")

def start_background_comprehensive_scraping():
    """Background scraping indítása"""
    def scraping_worker():
        while True:
            try:
                logger.info("Background scraping indítása...")
                run_comprehensive_scraping()
                logger.info("Background scraping befejezve, várakozás 2 órát...")
                time.sleep(7200)  # 2 óra
            except Exception as e:
                logger.error(f"Background scraping worker hiba: {e}")
                time.sleep(600)  # 10 perc hiba esetén

    thread = threading.Thread(target=scraping_worker, daemon=True, name="ScrapingWorker")
    thread.start()
    logger.info("Background scraping thread elindítva")

