<body>
    <div class="container">
        <header>
            <h1>🤖 AI Akció Figyelő 💰</h1>
            <p>Valós idejű webáruház akció scraper</p>
        </header>

        <div class="stats">
            <div class="stat-box">
                <strong id="productCount">0</strong>
                <span>Termék</span>
            </div>
            <div class="stat-box">
                <strong id="lastUpdate">-</strong>
                <span>Utolsó frissítés</span>
            </div>
        </div>

        <div class="controls">
            <input type="text" id="searchInput" placeholder="Keresés termékek között..." style="width: 300px;">
            <button onclick="searchProducts()">🔍 Keresés</button>
            <button onclick="refreshData()">🔄 Frissítés</button>
            <button onclick="loadProducts()">📋 Mind betöltése</button>
        </div>

        <div id="productsContainer" class="loading">
            <div class="spinner"></div>
            <p>Betöltés...</p>
        </div>
    </div>

    <script>
        async function loadProducts() {
            try {
                const response = await fetch('/api/products');
                const data = await response.json();

                document.getElementById('productCount').textContent = data.total_count;
                document.getElementById('lastUpdate').textContent = data.last_update ? 
                    new Date(data.last_update).toLocaleString('hu-HU') : '-';

