class TurboScraper:
    def __init__(self):
        self.session: Optional[aiohttp.ClientSession] = None

    async def create_session(self):
        """Ultra-gyors session beállítás"""
        if self.session is None or self.session.closed:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'hu-HU,hu;q=0.9',
                'Connection': 'keep-alive'
            }

            # AGGRESSIVE SETTINGS - GYORSASÁG!
            timeout = aiohttp.ClientTimeout(total=10, connect=5, sock_read=5)
            connector = aiohttp.TCPConnector(
                limit=100,  # 100 párhuzamos kapcsolat!
                ttl_dns_cache=600,
                ssl=False,
                force_close=False,
                enable_cleanup_closed=True
            )

            self.session = aiohttp.ClientSession(
                headers=headers,
                timeout=timeout,
                connector=connector
            )

    async def close_session(self):
        if self.session and not self.session.closed:
            await self.session.close()
            await asyncio.sleep(0.1)

    async def fetch_fast(self, url: str) -> str:
        """Ultra-gyors fetch NINCS SLEEP!"""
        try:
            await self.create_session()
            async with self.session.get(url, ssl=False) as response:
                if response.status == 200:
                    return await response.text(errors='ignore')
        except:
            pass
        return ""

    def parse_price(self, text: str) -> float:
        """Gyors ár parse"""
        try:
            if not text:
                return 0.0
            numbers = re.sub(r'[^\d.,]', '', text).replace(',', '.')
            match = re.search(r'[\d.]+', numbers)
            return float(match.group()) if match else 0.0
        except:
            return 0.0

    def calc_discount(self, old: float, new: float) -> float:
        """Gyors kedvezmény számítás"""
        try:
            if old > 0 and new > 0 and old > new:
                return round(((old - new) / old) * 100, 1)
        except:
            pass
        return 0.0

    async def scrape_url_fast(self, url: str, site: str, config: Dict) -> List[Dict]:
        """ULTRA-GYORS scraping egyetlen URL-hez"""
        products = []

        try:
            html = await self.fetch_fast(url)
            if not html or len(html) < 100:
                return []

            soup = BeautifulSoup(html, 'html.parser')
            items = soup.select(config['product'])[:30]  # Max 30 termék/oldal

            for item in items:
                try:
                    # Gyors elem keresés
                    title_elem = item.select_one(config['title'])
                    price_elem = item.select_one(config['price'])

                    if not title_elem or not price_elem:
                        continue

                    title = title_elem.get_text(strip=True)
                    price = self.parse_price(price_elem.get_text(strip=True))

                    if not title or price <= 0:
                        continue

                    # Régi ár
                    old_price = price
                    old_elem = item.select_one(config['old_price'])
                    if old_elem:
                        old_price = self.parse_price(old_elem.get_text(strip=True))
                        if old_price <= 0:
                            old_price = price

                    # Kedvezmény
                    discount = 0.0
                    disc_elem = item.select_one(config['discount'])
                    if disc_elem:
                        disc_text = disc_elem.get_text(strip=True)
                        match = re.search(r'(\d+)%', disc_text)
                        if match:
                            discount = float(match.group(1))

                    if discount == 0.0:
                        discount = self.calc_discount(old_price, price)

                    # Link
                    link = ""
                    link_elem = item.select_one('a')
                    if link_elem and link_elem.get('href'):
                        link = urljoin(config['base'], link_elem.get('href'))

                    products.append({
                        'site': site,
                        'title': title[:150],
                        'current_price': round(price, 2),
                        'original_price': round(old_price, 2),
                        'discount_percent': round(discount, 1),
                        'discount_amount': round(max(0, old_price - price), 2),
                        'link': link,
                        'scraped_at': datetime.now().isoformat()
                    })

                except:
                    continue

        except Exception as e:
            logger.debug(f"Scrape error {url}: {e}")

        return products

    async def scrape_site_turbo(self, site_name: str, config: Dict) -> List[Dict]:
        """Egy webhely ÖSSZES URL-je párhuzamosan - TURBO MODE!"""
        logger.info(f"🚀 {site_name} - TURBO MODE")

        # MINDEN URL párhuzamosan!
        tasks = [
            self.scrape_url_fast(url, site_name, config)
            for url in config['urls']
        ]

        results = await asyncio.gather(*tasks, return_exceptions=True)

        # Flatten
        all_products = []
        for result in results:
            if isinstance(result, list):
                all_products.extend(result)

        logger.info(f"✓ {site_name}: {len(all_products)} termék")
        return all_products

async def turbo_scrape_all():
    """MINDEN WEBHELY PÁRHUZAMOSAN - ULTRA TURBO! 🚀"""
    global scraped_data, last_update, scraping_in_progress

    if scraping_in_progress:
        return

    scraping_in_progress = True
    start_time = time.time()
    logger.info("⚡ TURBO SCRAPING START ⚡")

    scraper = TurboScraper()

    try:
        await scraper.create_session()

        # MINDEN WEBHELY EGYSZERRE! 🔥
        tasks = [
            scraper.scrape_site_turbo(site_name, config)
            for site_name, config in WEBSITES.items()
        ]

        results = await asyncio.gather(*tasks, return_exceptions=True)

        # Összes termék összegyűjtése
        all_products = []
        for result in results:
            if isinstance(result, list):
                all_products.extend(result)

        # Rendezés kedvezmény szerint
        all_products.sort(key=lambda x: x.get('discount_percent', 0), reverse=True)

        # Deduplikáció
        seen = set()
        unique_products = []
        for p in all_products:
            key = f"{p['site']}_{p['title']}"
            if key not in seen:
                seen.add(key)
                unique_products.append(p)

        scraped_data = unique_products
        last_update = datetime.now()

        elapsed = time.time() - start_time
        logger.info(f"⚡ TURBO COMPLETE: {len(unique_products)} termék {elapsed:.2f}s alatt! ⚡")

    except Exception as e:
        logger.error(f"Turbo scrape hiba: {e}")
    finally:
        await scraper.close_session()
        scraping_in_progress = False

def run_turbo_scraping():
    """Turbo scraping futtatása új event loop-pal"""
    try:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        loop.run_until_complete(turbo_scrape_all())
        loop.close()
    except Exception as e:
        logger.error(f"Run turbo hiba: {e}")

def start_background_turbo():
    """Background turbo scraping"""
    def worker():
        while True:
            try:
                run_turbo_scraping()
                time.sleep(300)  # 5 perc
            except Exception as e:
                logger.error(f"Background hiba: {e}")
                time.sleep(60)

    thread = threading.Thread(target=worker, daemon=True, name="TurboWorker")
    thread.start()

