class AIEnhancedCrawler:
    """100% VALÓDI AI-ENHANCED FULL SITE CRAWLER"""

    def __init__(self, site_name: str, config: Dict):
        self.site_name = site_name
        self.config = config
        self.session: Optional[aiohttp.ClientSession] = None
        self.visited_urls: Set[str] = set()
        self.urls_to_visit: deque = deque(config['start_urls'])
        self.products: List[Dict] = []
        self.all_links_found: Set[str] = set()
        self.ai_discovered_urls: Set[str] = set()
        self.ai_enhanced_products: int = 0

    async def create_session(self):
        """HTTP session létrehozása"""
        if self.session is None or self.session.closed:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'hu-HU,hu;q=0.9,en-US;q=0.8,en;q=0.7',
                'Accept-Encoding': 'gzip, deflate, br',
                'Connection': 'keep-alive',
                'Upgrade-Insecure-Requests': '1',
                'Sec-Fetch-Dest': 'document',
                'Sec-Fetch-Mode': 'navigate',
                'Sec-Fetch-Site': 'none',
                'Cache-Control': 'max-age=0'
            }

            timeout = aiohttp.ClientTimeout(total=30, connect=10, sock_read=20)
            connector = aiohttp.TCPConnector(
                limit=50,
                ttl_dns_cache=600,
                ssl=False,
                force_close=False
            )

            self.session = aiohttp.ClientSession(
                headers=headers,
                timeout=timeout,
                connector=connector
            )

    async def close_session(self):
        if self.session and not self.session.closed:
            await self.session.close()
            await asyncio.sleep(0.25)

    async def exa_discover_urls(self):
        """EXA AI - VALÓDI URL DISCOVERY"""
        if not exa_client:
            logger.info(f"[{self.site_name}] Exa AI nem elérhető - skip")
            return

        try:
            logger.info(f"[{self.site_name}] 🤖 EXA AI URL discovery...")

            domain = urlparse(self.config['base_url']).netloc

            # Minden search query-t párhuzamosan futtatunk
            for query in self.config.get('ai_search_queries', ['akció']):
                try:
                    search_query = f"site:{domain} {query}"

                    # VALÓDI Exa search
                    loop = asyncio.get_event_loop()
                    result = await loop.run_in_executor(
                        None,
                        lambda: exa_client.search(
                            query=search_query,
                            num_results=30,
                            use_autoprompt=True,
                            start_published_date="2024-01-01"
                        )
                    )

                    # URL-ek kinyerése
                    for item in result.results:
                        if item.url:
                            normalized = self.normalize_url(item.url)
                            if self.is_valid_url(normalized):
                                self.urls_to_visit.append(normalized)
                                self.ai_discovered_urls.add(normalized)
                                self.all_links_found.add(normalized)

                    logger.info(f"[{self.site_name}] Exa query '{query}': {len(result.results)} URL")

                except Exception as e:
                    logger.debug(f"Exa search error for '{query}': {e}")

                # Rate limiting
                await asyncio.sleep(0.5)

            logger.info(f"[{self.site_name}] ✅ Exa összesen: {len(self.ai_discovered_urls)} URL")

        except Exception as e:
            logger.error(f"[{self.site_name}] Exa discovery hiba: {e}")

    async def grok_analyze_page(self, html: str, url: str) -> Dict:
        """GROK AI - VALÓDI OLDAL ELEMZÉS"""
        if not xai_client:
            return {}

        try:
            # HTML snippet (első 4000 karakter)
            html_snippet = html[:4000] if len(html) > 4000 else html

            prompt = f"""Elemezd ezt a magyar webáruház oldalt és találd meg a termékeket.

URL: {url}

Keress:
- Termék címeket
- Árakat (Ft)
- Kedvezményeket (%)
- Termék linkeket

Válaszolj JSON formátumban:
{{
    "products": [
        {{"title": "...", "price": 12990, "discount": 20, "link": "..."}},
        ...
    ],
    "category_links": ["...", "..."],
    "pagination_links": ["...", "..."]
}}

HTML tartalom:
{html_snippet}
"""

            loop = asyncio.get_event_loop()
            response = await loop.run_in_executor(
                None,
                lambda: xai_client.chat.completions.create(
                    model="grok-beta",
                    messages=[
                        {"role": "system", "content": "Te egy webáruház elemző AI vagy. Csak JSON-t válaszolsz."},
                        {"role": "user", "content": prompt}
                    ],
                    max_tokens=2000,
                    temperature=0.1
                )
            )

            result_text = response.choices[0].message.content

            # JSON extract
            json_match = re.search(r'\{.*\}', result_text, re.DOTALL)
            if json_match:
                return json.loads(json_match.group())

            return {}

        except Exception as e:
            logger.debug(f"Grok analyze error: {e}")
            return {}

    def is_valid_url(self, url: str) -> bool:
        """URL validáció"""
        try:
            parsed = urlparse(url)

            if parsed.scheme not in ['http', 'https']:
                return False

            domain_ok = any(domain in parsed.netloc for domain in self.config['allowed_domains'])
            if not domain_ok:
                return False

            excluded_extensions = ['.pdf', '.jpg', '.jpeg', '.png', '.gif', '.zip', '.rar', '.exe', '.css', '.js', '.xml', '.json']
            if any(parsed.path.lower().endswith(ext) for ext in excluded_extensions):
                return False

            excluded_paths = ['/cdn-cgi/', '/wp-admin/', '/admin/', '/_next/', '/static/']
            if any(excluded in parsed.path for excluded in excluded_paths):
                return False

            return True

        except:
            return False

    def normalize_url(self, url: str) -> str:
        """URL normalizálás"""
        try:
            parsed = urlparse(url)
            if parsed.query:
                allowed_params = ['page', 'p', 'category', 'cat', 'id', 'q', 'search']
                query_params = parse_qs(parsed.query)
                filtered_params = {k: v for k, v in query_params.items() if k in allowed_params}
                if filtered_params:
                    from urllib.parse import urlencode
                    new_query = urlencode(filtered_params, doseq=True)
                    return f"{parsed.scheme}://{parsed.netloc}{parsed.path}?{new_query}"

            return f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
        except:
            return url

    async def fetch_page(self, url: str) -> Optional[str]:
        """Oldal letöltése"""
        try:
            await self.create_session()

            async with self.session.get(url, ssl=False, allow_redirects=True) as response:
                if response.status == 200:
                    content_type = response.headers.get('Content-Type', '')
                    if 'text/html' in content_type:
                        html = await response.text(errors='ignore')
                        return html

        except asyncio.TimeoutError:
            logger.debug(f"Timeout: {url}")
        except Exception as e:
            logger.debug(f"Fetch error {url}: {str(e)[:100]}")

        return None

    def extract_all_links(self, html: str, current_url: str) -> Set[str]:
        """Link kinyerés"""
        links = set()

        try:
            soup = BeautifulSoup(html, 'html.parser')

            for link_tag in soup.find_all('a', href=True):
                href = link_tag.get('href', '').strip()
                if href:
                    absolute_url = urljoin(current_url, href)
                    normalized = self.normalize_url(absolute_url)

                    if self.is_valid_url(normalized):
                        links.add(normalized)

            for form in soup.find_all('form', action=True):
                action = form.get('action', '').strip()
                if action:
                    absolute_url = urljoin(current_url, action)
                    normalized = self.normalize_url(absolute_url)
                    if self.is_valid_url(normalized):
                        links.add(normalized)

        except Exception as e:
            logger.debug(f"Link extraction error: {e}")

        return links

    def parse_price(self, text: str) -> float:
        """Ár parsing"""
        try:
            if not text:
                return 0.0

            cleaned = re.sub(r'[^\d.,]', '', text)
            cleaned = cleaned.replace(',', '.')

            match = re.search(r'\d+\.?\d*', cleaned)
            if match:
                return float(match.group())
        except:
            pass
        return 0.0

    def calculate_discount(self, original: float, current: float) -> float:
        """Kedvezmény számítás"""
        try:
            if original > 0 and current > 0 and original > current:
                return round(((original - current) / original) * 100, 1)
        except:
            pass
        return 0.0

    def extract_products_from_page(self, html: str, url: str, ai_data: Dict = None) -> List[Dict]:
        """Termékek kinyerése (hagyományos + AI)"""
        products = []

        try:
            soup = BeautifulSoup(html, 'html.parser')
            selectors = self.config['selectors']

            product_elements = soup.select(selectors['product'])

            for element in product_elements:
                try:
                    title_elem = element.select_one(selectors['title'])
                    if not title_elem:
                        continue

                    title = title_elem.get_text(strip=True)
                    if not title or len(title) < 3:
                        continue

                    price_elem = element.select_one(selectors['price'])
                    if not price_elem:
                        continue

                    current_price = self.parse_price(price_elem.get_text(strip=True))
                    if current_price <= 0:
                        continue

                    original_price = current_price
                    original_elem = element.select_one(selectors['original_price'])
                    if original_elem:
                        parsed_original = self.parse_price(original_elem.get_text(strip=True))
                        if parsed_original > 0:
                            original_price = parsed_original

                    discount_percent = 0.0
                    discount_elem = element.select_one(selectors['discount'])
                    if discount_elem:
                        discount_text = discount_elem.get_text(strip=True)
                        percent_match = re.search(r'(\d+)\s*%', discount_text)
                        if percent_match:
                            discount_percent = float(percent_match.group(1))

                    if discount_percent == 0.0:
                        discount_percent = self.calculate_discount(original_price, current_price)

                    product_link = ""
                    link_elem = element.select_one('a[href]')
                    if link_elem:
                        href = link_elem.get('href', '')
                        if href:
                            product_link = urljoin(self.config['base_url'], href)

                    # AI enhanced flag
                    ai_enhanced = bool(ai_data and ai_data.get('products'))
                    if ai_enhanced:
                        self.ai_enhanced_products += 1

                    product = {
                        'site': self.site_name,
                        'title': title[:200],
                        'current_price': round(current_price, 2),
                        'original_price': round(original_price, 2),
                        'discount_percent': round(discount_percent, 1),
                        'discount_amount': round(max(0, original_price - current_price), 2),
                        'link': product_link,
                        'source_url': url,
                        'scraped_at': datetime.now().isoformat(),
                        'ai_enhanced': ai_enhanced
                    }

                    products.append(product)

                except Exception as e:
                    logger.debug(f"Product parse error: {e}")
                    continue

            # AI által talált extra termékek hozzáadása
            if ai_data and ai_data.get('products'):
                for ai_product in ai_data['products']:
                    try:
                        if ai_product.get('title') and ai_product.get('price'):
                            product = {
                                'site': self.site_name,
                                'title': ai_product['title'][:200],
                                'current_price': float(ai_product['price']),
                                'original_price': float(ai_product.get('original_price', ai_product['price'])),
                                'discount_percent': float(ai_product.get('discount', 0)),
                                'discount_amount': 0,
                                'link': ai_product.get('link', ''),
                                'source_url': url,
                                'scraped_at': datetime.now().isoformat(),
                                'ai_enhanced': True
                            }
                            products.append(product)
                            self.ai_enhanced_products += 1
                    except:
                        continue

        except Exception as e:
            logger.error(f"Page parse error: {e}")

        return products

    async def crawl_full_site(self, max_pages: int = 1000):
        """TELJES CRAWLING AI-VAL"""

        logger.info(f"🔥 [{self.site_name}] AI-ENHANCED CRAWLING START")

        pages_crawled = 0

        try:
            await self.create_session()

            # 1. EXA AI URL DISCOVERY
            await self.exa_discover_urls()

            # 2. Sitemap
            await self.try_load_sitemap()

            # 3. FŐCIKLUS
            while self.urls_to_visit and pages_crawled < max_pages:
                batch_size = 10
                tasks = []
                batch_urls = []

                for _ in range(min(batch_size, len(self.urls_to_visit))):
                    if self.urls_to_visit:
                        url = self.urls_to_visit.popleft()
                        if url not in self.visited_urls:
                            batch_urls.append(url)
                            tasks.append(self.process_url(url))

                if tasks:
                    results = await asyncio.gather(*tasks, return_exceptions=True)

                    for url, result in zip(batch_urls, results):
                        if isinstance(result, tuple):
                            new_links, new_products = result

                            for link in new_links:
                                if link not in self.visited_urls and link not in self.all_links_found:
                                    self.urls_to_visit.append(link)
                                    self.all_links_found.add(link)

                            self.products.extend(new_products)

                        self.visited_urls.add(url)
                        pages_crawled += 1

                if pages_crawled % 50 == 0:
                    logger.info(f"[{self.site_name}] {pages_crawled} oldal, {len(self.products)} termék, {self.ai_enhanced_products} AI-enhanced")

                await asyncio.sleep(0.5)

        except Exception as e:
            logger.error(f"[{self.site_name}] Crawl error: {e}")

        finally:
            await self.close_session()

        logger.info(f"✅ [{self.site_name}] KÉSZ: {pages_crawled} oldal, {len(self.products)} termék, {self.ai_enhanced_products} AI-enhanced, {len(self.ai_discovered_urls)} Exa URL")

        return self.products

    async def try_load_sitemap(self):
        """Sitemap betöltés"""
        try:
            sitemap_url = urljoin(self.config['base_url'], '/sitemap.xml')
            html = await self.fetch_page(sitemap_url)

            if html:
                urls = re.findall(r'<loc>(.*?)</loc>', html)
                for url in urls[:500]:
                    normalized = self.normalize_url(url)
                    if self.is_valid_url(normalized):
                        self.urls_to_visit.append(normalized)
                        self.all_links_found.add(normalized)

                logger.info(f"[{self.site_name}] Sitemap: {len(urls)} URL")
        except:
            pass

    async def process_url(self, url: str) -> tuple:
        """URL feldolgozás AI-val"""
        new_links = set()
        new_products = []

        try:
            logger.debug(f"[{self.site_name}] Crawl: {url}")

            html = await self.fetch_page(url)

            if html:
                # Linkek
                new_links = self.extract_all_links(html, url)

                # AI elemzés (ha van Grok)
                ai_data = {}
                if xai_client and len(html) > 500:
                    ai_data = await self.grok_analyze_page(html, url)

                    # AI által talált linkek hozzáadása
                    if ai_data.get('category_links'):
                        for link in ai_data['category_links']:
                            full_link = urljoin(self.config['base_url'], link)
                            normalized = self.normalize_url(full_link)
                            if self.is_valid_url(normalized):
                                new_links.add(normalized)

                    if ai_data.get('pagination_links'):
                        for link in ai_data['pagination_links']:
                            full_link = urljoin(self.config['base_url'], link)
                            normalized = self.normalize_url(full_link)
                            if self.is_valid_url(normalized):
                                new_links.add(normalized)

                # Termékek (hagyományos + AI)
                new_products = self.extract_products_from_page(html, url, ai_data)

        except Exception as e:
            logger.debug(f"Process URL error {url}: {e}")

        return (new_links, new_products)

async def ai_crawl_all_sites():
    """MINDEN WEBHELY AI-ENHANCED CRAWLING"""
    global scraped_data, last_update, scraping_in_progress, crawl_stats

    if scraping_in_progress:
        logger.info("Crawling már fut...")
        return

    scraping_in_progress = True
    start_time = time.time()

    logger.info("=" * 80)
    logger.info("🤖🔥 AI-ENHANCED TELJES WEBOLDAL CRAWLING START 🔥🤖")
    logger.info("=" * 80)

    all_products = []
    stats = {}

    try:
        crawlers = [
            AIEnhancedCrawler(site_name, config)
            for site_name, config in WEBSITES.items()
        ]

        tasks = [
            crawler.crawl_full_site(max_pages=1000)
            for crawler in crawlers
        ]

        results = await asyncio.gather(*tasks, return_exceptions=True)

        for crawler, result in zip(crawlers, results):
            if isinstance(result, list):
                all_products.extend(result)
                stats[crawler.site_name] = {
                    'pages_crawled': len(crawler.visited_urls),
                    'products_found': len(result),
                    'links_discovered': len(crawler.all_links_found),
                    'ai_discovered_urls': len(crawler.ai_discovered_urls),
                    'ai_enhanced_products': crawler.ai_enhanced_products
                }

        # Deduplikáció
        seen = set()
        unique_products = []

        for p in all_products:
            key = f"{p['site']}_{p['title']}_{p['current_price']}"
            if key not in seen:
                seen.add(key)
                unique_products.append(p)

        unique_products.sort(key=lambda x: x.get('discount_percent', 0), reverse=True)

        scraped_data = unique_products
        last_update = datetime.now()
        crawl_stats = stats

        elapsed = time.time() - start_time
        total_ai_enhanced = sum(s['ai_enhanced_products'] for s in stats.values())
        total_exa_urls = sum(s['ai_discovered_urls'] for s in stats.values())

        logger.info("=" * 80)
        logger.info(f"✅ AI-ENHANCED CRAWLING KÉSZ {elapsed:.1f} másodperc alatt!")
        logger.info(f"📊 {len(unique_products)} termék | 🤖 {total_ai_enhanced} AI-enhanced | 🔍 {total_exa_urls} Exa URL")

        for site, stat in stats.items():
            logger.info(f"   • {site}: {stat['pages_crawled']} oldal, {stat['products_found']} termék, {stat['ai_enhanced_products']} AI")

        logger.info("=" * 80)

    except Exception as e:
        logger.error(f"Global crawl error: {e}")
        import traceback
        traceback.print_exc()

    finally:
        scraping_in_progress = False

def run_ai_crawl():
    """AI crawl futtatása"""
    try:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        loop.run_until_complete(ai_crawl_all_sites())
        loop.close()
    except Exception as e:
        logger.error(f"Run AI crawl error: {e}")

def start_background_ai_crawler():
    """Background AI crawler"""
    def worker():
        while True:
            try:
                logger.info("🔄 Scheduled AI crawl...")
                run_ai_crawl()
                logger.info("⏰ Next crawl in 1 hour...")
                time.sleep(3600)
            except Exception as e:
                logger.error(f"Background worker error: {e}")
                time.sleep(600)

    thread = threading.Thread(target=worker, daemon=True, name="AICrawlerWorker")
    thread.start()
    logger.info("✅ Background AI crawler started")

