class SimpleScraper:
    def __init__(self, site_name: str, config: Dict):
        self.site_name = site_name
        self.config = config
        self.session = None
        self.products = []

    async def init_session(self):
        if not self.session or self.session.closed:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language': 'hu-HU,hu;q=0.9',
            }
            timeout = aiohttp.ClientTimeout(total=30)
            self.session = aiohttp.ClientSession(headers=headers, timeout=timeout)

    async def close_session(self):
        if self.session and not self.session.closed:
            await self.session.close()

    async def fetch(self, url: str) -> Optional[str]:
        try:
            logger.info(f"[{self.site_name}] Fetch: {url}")
            await self.init_session()

            async with self.session.get(url, ssl=False) as resp:
                logger.info(f"[{self.site_name}] Status: {resp.status}")

                if resp.status == 200:
                    html = await resp.text()
                    logger.info(f"[{self.site_name}] HTML length: {len(html)}")
                    return html
                else:
                    logger.warning(f"[{self.site_name}] Bad status: {resp.status}")
        except Exception as e:
            logger.error(f"[{self.site_name}] Fetch error: {e}")

        return None

    def parse_price(self, text: str) -> float:
        try:
            numbers = re.sub(r'[^\d.,]', '', text)
            numbers = numbers.replace(',', '.')
            match = re.search(r'\d+\.?\d*', numbers)
            if match:
                return float(match.group())
        except:
            pass
        return 0.0

    def extract_products(self, html: str, url: str) -> List[Dict]:
        products = []

        try:
            soup = BeautifulSoup(html, 'html.parser')
            selectors = self.config['selectors']

            logger.info(f"[{self.site_name}] Keresés selector: {selectors['product']}")

            items = soup.select(selectors['product'])
            logger.info(f"[{self.site_name}] Találat: {len(items)} elem")

            # Ha nincs találat, próbáljunk meg mindent ami terméknek tűnik
            if len(items) == 0:
                logger.warning(f"[{self.site_name}] Nincs találat, próbálok általános keresést...")
                items = soup.find_all(['article', 'div'], class_=re.compile(r'product|item', re.I))
                logger.info(f"[{self.site_name}] Általános keresés: {len(items)} elem")

            for i, item in enumerate(items[:50]):
                try:
                    # Cím
                    title_elem = item.select_one(selectors['title'])
                    if not title_elem:
                        # Fallback
                        title_elem = item.find(['h1', 'h2', 'h3', 'h4'])

                    if not title_elem:
                        continue

                    title = title_elem.get_text(strip=True)
                    if not title or len(title) < 3:
                        continue

                    # Ár
                    price_elems = item.select(selectors['price'])
                    if not price_elems:
                        price_elems = item.find_all(class_=re.compile(r'price', re.I))

                    current_price = 0.0
                    original_price = 0.0

                    for price_elem in price_elems:
                        price_text = price_elem.get_text(strip=True)
                        price_val = self.parse_price(price_text)

                        if price_val > 0:
                            class_str = ' '.join(price_elem.get('class', []))
                            if 'old' in class_str.lower() or 'original' in class_str.lower():
                                original_price = max(original_price, price_val)
                            else:
                                if current_price == 0:
                                    current_price = price_val

                    if current_price == 0:
                        continue

                    if original_price == 0:
                        original_price = current_price

                    # Kedvezmény
                    discount = 0.0
                    if original_price > current_price:
                        discount = round(((original_price - current_price) / original_price) * 100, 1)

                    # Link
                    link_elem = item.select_one('a[href]')
                    link = ""
                    if link_elem:
                        href = link_elem.get('href', '')
                        if href:
                            link = urljoin(self.config['base'], href)

                    product = {
                        'site': self.site_name,
                        'title': title[:200],
                        'current_price': round(current_price, 2),
                        'original_price': round(original_price, 2),
                        'discount_percent': round(discount, 1),
                        'discount_amount': round(original_price - current_price, 2),
                        'link': link,
                        'source_url': url,
                        'scraped_at': datetime.now().isoformat()
                    }

                    products.append(product)

                    if i < 3:  # Debug első 3 termék
                        logger.debug(f"[{self.site_name}] Termék {i+1}: {title[:50]} - {current_price} Ft")

                except Exception as e:
                    logger.debug(f"[{self.site_name}] Termék parse hiba: {e}")
                    continue

            logger.info(f"[{self.site_name}] Összesen: {len(products)} termék")

        except Exception as e:
            logger.error(f"[{self.site_name}] Parse hiba: {e}")

        return products

    async def scrape(self) -> List[Dict]:
        logger.info(f"[{self.site_name}] Scraping indítása...")

        try:
            await self.init_session()

            for url in self.config['urls']:
                html = await fetch(url)

                if html:
                    products = self.extract_products(html, url)
                    self.products.extend(products)

                await asyncio.sleep(2)

        except Exception as e:
            logger.error(f"[{self.site_name}] Scrape hiba: {e}")
        finally:
            await self.close_session()

        logger.info(f"[{self.site_name}] Kész: {len(self.products)} termék")
        return self.products

async def scrape_all():
    global scraped_data, last_update, scraping_in_progress, debug_info

    if scraping_in_progress:
        return

    scraping_in_progress = True
    start = time.time()

    logger.info("=" * 60)
    logger.info("SCRAPING START")
    logger.info("=" * 60)

    all_products = []
    debug_info = []

    try:
        for site_name, config in SITES.items():
            try:
                scraper = SimpleScraper(site_name, config)
                products = await scraper.scrape()
                all_products.extend(products)

                debug_info.append({
                    'site': site_name,
                    'products_found': len(products),
                    'urls_scraped': len(config['urls'])
                })

                await asyncio.sleep(3)

            except Exception as e:
                logger.error(f"Site {site_name} hiba: {e}")
                debug_info.append({
                    'site': site_name,
                    'error': str(e)
                })

        # Deduplikáció
        seen = set()
        unique = []
        for p in all_products:
            key = f"{p['site']}_{p['title']}"
            if key not in seen:
                seen.add(key)
                unique.append(p)

        unique.sort(key=lambda x: x.get('discount_percent', 0), reverse=True)

        scraped_data = unique
        last_update = datetime.now()

        elapsed = time.time() - start

        logger.info("=" * 60)
        logger.info(f"SCRAPING KÉSZ: {len(unique)} termék {elapsed:.1f}s alatt")
        for info in debug_info:
            logger.info(f"  {info}")
        logger.info("=" * 60)

    except Exception as e:
        logger.error(f"Global hiba: {e}")
        import traceback
        traceback.print_exc()

    finally:
        scraping_in_progress = False

def run_scrape():
    try:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        loop.run_until_complete(scrape_all())
        loop.close()
    except Exception as e:
        logger.error(f"Run hiba: {e}")

def background_worker():
    while True:
        try:
            logger.info("Scraping indítása...")
            run_scrape()
            logger.info("Következő scraping 30 perc múlva")
            time.sleep(1800)
        except Exception as e:
            logger.error(f"Worker hiba: {e}")
            time.sleep(300)

