class WebCrawler:
    def __init__(self, site_name: str, config: Dict):
        self.site_name = site_name
        self.config = config
        self.session: Optional[aiohttp.ClientSession] = None
        self.visited_urls: Set[str] = set()
        self.urls_to_visit: deque = deque(config['start_urls'])
        self.products: List[Dict] = []
        self.all_links: Set[str] = set()
        self.ai_discovered: Set[str] = set()
        self.ai_enhanced_count = 0

    async def init_session(self):
        if not self.session or self.session.closed:
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'hu-HU,hu;q=0.9,en-US;q=0.8,en;q=0.7',
                'Accept-Encoding': 'gzip, deflate, br',
                'Connection': 'keep-alive',
                'Upgrade-Insecure-Requests': '1'
            }

            timeout = aiohttp.ClientTimeout(total=30, connect=10, sock_read=20)
            connector = aiohttp.TCPConnector(
                limit=50,
                ttl_dns_cache=600,
                ssl=False
            )

            self.session = aiohttp.ClientSession(
                headers=headers,
                timeout=timeout,
                connector=connector
            )

    async def close_session(self):
        if self.session and not self.session.closed:
            await self.session.close()
            await asyncio.sleep(0.25)

    def is_valid_url(self, url: str) -> bool:
        try:
            parsed = urlparse(url)

            if parsed.scheme not in ['http', 'https']:
                return False

            domain_ok = any(d in parsed.netloc for d in self.config['allowed_domains'])
            if not domain_ok:
                return False

            excluded_ext = ['.pdf', '.jpg', '.jpeg', '.png', '.gif', '.zip', '.css', '.js', '.xml', '.json']
            if any(parsed.path.lower().endswith(ext) for ext in excluded_ext):
                return False

            excluded_paths = ['/cdn-cgi/', '/wp-admin/', '/admin/', '/_next/', '/static/']
            if any(excl in parsed.path for excl in excluded_paths):
                return False

            return True
        except:
            return False

    def normalize_url(self, url: str) -> str:
        try:
            parsed = urlparse(url)
            if parsed.query:
                allowed_params = ['page', 'p', 'category', 'cat', 'id', 'q', 'search']
                params = parse_qs(parsed.query)
                filtered = {k: v for k, v in params.items() if k in allowed_params}
                if filtered:
                    from urllib.parse import urlencode
                    query = urlencode(filtered, doseq=True)
                    return f"{parsed.scheme}://{parsed.netloc}{parsed.path}?{query}"

            return f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
        except:
            return url

    async def exa_discover(self):
        if not exa_client:
            return

        try:
            logger.info(f"[{self.site_name}] Exa AI discovery...")

            domain = urlparse(self.config['base_url']).netloc

            for query in self.config.get('ai_queries', ['akció']):
                try:
                    search_query = f"site:{domain} {query}"

                    loop = asyncio.get_event_loop()
                    result = await loop.run_in_executor(
                        None,
                        lambda: exa_client.search(
                            query=search_query,
                            num_results=30,
                            use_autoprompt=True
                        )
                    )

                    for item in result.results:
                        if item.url:
                            normalized = self.normalize_url(item.url)
                            if self.is_valid_url(normalized):
                                self.urls_to_visit.append(normalized)
                                self.ai_discovered.add(normalized)
                                self.all_links.add(normalized)

                    logger.info(f"[{self.site_name}] Exa '{query}': {len(result.results)} URLs")

                except Exception as e:
                    logger.debug(f"Exa query error: {e}")

                await asyncio.sleep(0.5)

            logger.info(f"[{self.site_name}] Exa total: {len(self.ai_discovered)} URLs")

        except Exception as e:
            logger.error(f"[{self.site_name}] Exa error: {e}")

    async def grok_analyze(self, html: str, url: str) -> Dict:
        if not xai_client:
            return {}

        try:
            snippet = html[:4000]

            prompt = f"""Elemezd ezt a magyar webáruház oldalt.

URL: {url}

Keress:
- Termékeket (cím, ár)
- Kategória linkeket
- Lapozási linkeket

JSON válasz:
{{
    "products": [{{"title": "...", "price": 12990}}],
    "category_links": ["..."],
    "pagination_links": ["..."]
}}

HTML:
{snippet}"""

            loop = asyncio.get_event_loop()
            response = await loop.run_in_executor(
                None,
                lambda: xai_client.chat.completions.create(
                    model="grok-beta",
                    messages=[
                        {"role": "system", "content": "JSON elemző AI vagy."},
                        {"role": "user", "content": prompt}
                    ],
                    max_tokens=2000,
                    temperature=0.1
                )
            )

            result_text = response.choices[0].message.content

            json_match = re.search(r'\{.*\}', result_text, re.DOTALL)
            if json_match:
                return json.loads(json_match.group())

            return {}

        except Exception as e:
            logger.debug(f"Grok error: {e}")
            return {}

    async def fetch(self, url: str) -> Optional[str]:
        try:
            await self.init_session()

            async with self.session.get(url, ssl=False, allow_redirects=True) as resp:
                if resp.status == 200:
                    content_type = resp.headers.get('Content-Type', '')
                    if 'text/html' in content_type:
                        return await resp.text(errors='ignore')

        except asyncio.TimeoutError:
            logger.debug(f"Timeout: {url}")
        except Exception as e:
            logger.debug(f"Fetch error {url}: {str(e)[:100]}")

        return None

    def extract_links(self, html: str, current_url: str) -> Set[str]:
        links = set()

        try:
            soup = BeautifulSoup(html, 'html.parser')

            for link in soup.find_all('a', href=True):
                href = link.get('href', '').strip()
                if href:
                    absolute = urljoin(current_url, href)
                    normalized = self.normalize_url(absolute)

                    if self.is_valid_url(normalized):
                        links.add(normalized)

        except Exception as e:
            logger.debug(f"Link extraction error: {e}")

        return links

    def parse_price(self, text: str) -> float:
        try:
            if not text:
                return 0.0

            cleaned = re.sub(r'[^\d.,]', '', text)
            cleaned = cleaned.replace(',', '.')

            match = re.search(r'\d+\.?\d*', cleaned)
            if match:
                return float(match.group())
        except:
            pass
        return 0.0

    def calc_discount(self, original: float, current: float) -> float:
        try:
            if original > 0 and current > 0 and original > current:
                return round(((original - current) / original) * 100, 1)
        except:
            pass
        return 0.0

    def extract_products(self, html: str, url: str, ai_data: Dict = None) -> List[Dict]:
        products = []

        try:
            soup = BeautifulSoup(html, 'html.parser')
            selectors = self.config['selectors']

            items = soup.select(selectors['product'])

            # Fallback if no results
            if not items:
                items = soup.find_all(['article', 'div'], class_=re.compile(r'product|item', re.I))

            for item in items[:50]:
                try:
                    # Title
                    title_elem = item.select_one(selectors['title'])
                    if not title_elem:
                        title_elem = item.find(['h1', 'h2', 'h3', 'h4'])

                    if not title_elem:
                        continue

                    title = title_elem.get_text(strip=True)
                    if not title or len(title) < 3:
                        continue

                    # Prices
                    price_elems = item.select(selectors['price'])
                    if not price_elems:
                        price_elems = item.find_all(class_=re.compile(r'price', re.I))

                    current_price = 0.0
                    original_price = 0.0

                    for price_elem in price_elems:
                        price_text = price_elem.get_text(strip=True)
                        price_val = self.parse_price(price_text)

                        if price_val > 0:
                            classes = ' '.join(price_elem.get('class', [])).lower()
                            if 'old' in classes or 'original' in classes or 'was' in classes:
                                original_price = max(original_price, price_val)
                            else:
                                if current_price == 0:
                                    current_price = price_val

                    if current_price == 0:
                        continue

                    if original_price == 0:
                        original_price = current_price

                    discount = self.calc_discount(original_price, current_price)

                    # Link
                    link_elem = item.select_one('a[href]')
                    link = ""
                    if link_elem:
                        href = link_elem.get('href', '')
                        if href:
                            link = urljoin(self.config['base_url'], href)

                    ai_enhanced = bool(ai_data and ai_data.get('products'))
                    if ai_enhanced:
                        self.ai_enhanced_count += 1

                    product = {
                        'site': self.site_name,
                        'title': title[:200],
                        'current_price': round(current_price, 2),
                        'original_price': round(original_price, 2),
                        'discount_percent': round(discount, 1),
                        'discount_amount': round(original_price - current_price, 2),
                        'link': link,
                        'source_url': url,
                        'scraped_at': datetime.now().isoformat(),
                        'ai_enhanced': ai_enhanced
                    }

                    products.append(product)

                except Exception as e:
                    logger.debug(f"Product parse error: {e}")
                    continue

            # AI products
            if ai_data and ai_data.get('products'):
                for ai_prod in ai_data['products']:
                    try:
                        if ai_prod.get('title') and ai_prod.get('price'):
                            product = {
                                'site': self.site_name,
                                'title': ai_prod['title'][:200],
                                'current_price': float(ai_prod['price']),
                                'original_price': float(ai_prod.get('original_price', ai_prod['price'])),
                                'discount_percent': float(ai_prod.get('discount', 0)),
                                'discount_amount': 0,
                                'link': ai_prod.get('link', ''),
                                'source_url': url,
                                'scraped_at': datetime.now().isoformat(),
                                'ai_enhanced': True
                            }
                            products.append(product)
                            self.ai_enhanced_count += 1
                    except:
                        continue

        except Exception as e:
            logger.error(f"Parse error: {e}")

        return products

    async def load_sitemap(self):
        try:
            sitemap_url = urljoin(self.config['base_url'], '/sitemap.xml')
            html = await self.fetch(sitemap_url)

            if html:
                urls = re.findall(r'<loc>(.*?)</loc>', html)
                for url in urls[:500]:
                    normalized = self.normalize_url(url)
                    if self.is_valid_url(normalized):
                        self.urls_to_visit.append(normalized)
                        self.all_links.add(normalized)

                logger.info(f"[{self.site_name}] Sitemap: {len(urls)} URLs")
        except:
            pass

    async def process_url(self, url: str) -> tuple:
        new_links = set()
        new_products = []

        try:
            logger.debug(f"[{self.site_name}] Processing: {url}")

            html = await self.fetch(url)

            if html:
                new_links = self.extract_links(html, url)

                ai_data = {}
                if xai_client and len(html) > 500:
                    ai_data = await self.grok_analyze(html, url)

                    if ai_data.get('category_links'):
                        for link in ai_data['category_links']:
                            full = urljoin(self.config['base_url'], link)
                            norm = self.normalize_url(full)
                            if self.is_valid_url(norm):
                                new_links.add(norm)

                    if ai_data.get('pagination_links'):
                        for link in ai_data['pagination_links']:
                            full = urljoin(self.config['base_url'], link)
                            norm = self.normalize_url(full)
                            if self.is_valid_url(norm):
                                new_links.add(norm)

                new_products = self.extract_products(html, url, ai_data)

        except Exception as e:
            logger.debug(f"Process error {url}: {e}")

        return (new_links, new_products)

    async def crawl(self, max_pages: int = 1000):
        logger.info(f"[{self.site_name}] Crawling started (max {max_pages} pages)")

        pages_crawled = 0

        try:
            await self.init_session()

            # Exa discovery
            await self.exa_discover()

            # Sitemap
            await self.load_sitemap()

            # Main crawl loop
            while self.urls_to_visit and pages_crawled < max_pages:
                batch_size = 10
                tasks = []
                batch_urls = []

                for _ in range(min(batch_size, len(self.urls_to_visit))):
                    if self.urls_to_visit:
                        url = self.urls_to_visit.popleft()
                        if url not in self.visited_urls:
                            batch_urls.append(url)
                            tasks.append(self.process_url(url))

                if tasks:
                    results = await asyncio.gather(*tasks, return_exceptions=True)

                    for url, result in zip(batch_urls, results):
                        if isinstance(result, tuple):
                            new_links, new_products = result

                            for link in new_links:
                                if link not in self.visited_urls and link not in self.all_links:
                                    self.urls_to_visit.append(link)
                                    self.all_links.add(link)

                            self.products.extend(new_products)

                        self.visited_urls.add(url)
                        pages_crawled += 1

                if pages_crawled % 50 == 0:
                    logger.info(f"[{self.site_name}] Progress: {pages_crawled} pages, {len(self.products)} products")

                await asyncio.sleep(0.5)

        except Exception as e:
            logger.error(f"[{self.site_name}] Crawl error: {e}")

        finally:
            await self.close_session()

        logger.info(f"[{self.site_name}] Finished: {pages_crawled} pages, {len(self.products)} products, {self.ai_enhanced_count} AI-enhanced")

        return self.products

async def crawl_all_sites():
    global scraped_data, last_update, scraping_in_progress, crawl_stats

    if scraping_in_progress:
        return

    scraping_in_progress = True
    start = time.time()

    logger.info("="*80)
    logger.info("FULL SITE CRAWLING STARTED")
    logger.info("="*80)

    all_products = []
    stats = {}

    try:
        crawlers = [WebCrawler(name, config) for name, config in WEBSITES.items()]

        tasks = [crawler.crawl(max_pages=1000) for crawler in crawlers]

        results = await asyncio.gather(*tasks, return_exceptions=True)

        for crawler, result in zip(crawlers, results):
            if isinstance(result, list):
                all_products.extend(result)
                stats[crawler.site_name] = {
                    'pages_crawled': len(crawler.visited_urls),
                    'products_found': len(result),
                    'links_discovered': len(crawler.all_links),
                    'ai_discovered': len(crawler.ai_discovered),
                    'ai_enhanced': crawler.ai_enhanced_count
                }

        # Dedup
        seen = set()
        unique = []

        for p in all_products:
            key = f"{p['site']}_{p['title']}_{p['current_price']}"
            if key not in seen:
                seen.add(key)
                unique.append(p)

        unique.sort(key=lambda x: x.get('discount_percent', 0), reverse=True)

        scraped_data = unique
        last_update = datetime.now()
        crawl_stats = stats

        elapsed = time.time() - start
        total_ai = sum(s.get('ai_enhanced', 0) for s in stats.values())
        total_exa = sum(s.get('ai_discovered', 0) for s in stats.values())

        logger.info("="*80)
        logger.info(f"CRAWLING COMPLETED: {len(unique)} products in {elapsed:.1f}s")
        logger.info(f"AI Stats: {total_ai} enhanced, {total_exa} Exa URLs")

        for site, stat in stats.items():
            logger.info(f"  {site}: {stat['pages_crawled']} pages, {stat['products_found']} products")

        logger.info("="*80)

    except Exception as e:
        logger.error(f"Crawl error: {e}")
        import traceback
        traceback.print_exc()

    finally:
        scraping_in_progress = False

def run_crawl():
    try:
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        loop.run_until_complete(crawl_all_sites())
        loop.close()
    except Exception as e:
        logger.error(f"Run error: {e}")

def background_worker():
    while True:
        try:
            run_crawl()
            logger.info("Next crawl in 1 hour")
            time.sleep(3600)
        except Exception as e:
            logger.error(f"Worker error: {e}")
            time.sleep(600)

